{"cmd":"python - <<'PY'
import pandas as pd

df=pd.read_csv('benchmark/data.csv')

def compute_inflections(series):
    yoy=series.pct_change()*100
    abs_sorted=yoy.dropna().abs().sort_values(ascending=False)
    return abs_sorted.head(5)

yearly=df.groupby('Year').agg(avg_price=('Price','mean'),avg_rating=('User Rating','mean'),avg_reviews=('Reviews','mean'))

for col in yearly.columns:
    top=compute_inflections(yearly[col])
    print('\n',col)
    for year,val in top.items():
        prev=yearly.loc[year-1,col]
        cur=yearly.loc[year,col]
        print(year, f"{val:+.2f}%", f"{prev:.2f} -> {cur:.2f}")
PY"}
